{"content": "import pytest

import click


def test_prompt_hide_input_error_message(runner):
    """When hide_input is True and validation fails, the error message
    should not show the user's input value."""
    @click.command()
    @click.option("--pin", prompt=True, hide_input=True, type=int)
    def cli(pin):
        click.echo(f"pin={pin}")

    # Provide invalid input first, then valid input to break the loop.
    result = runner.invoke(cli, input="not_a_number\n42\n")
    assert not result.exception
    # The error message should not contain the input value.
    assert "not_a_number" not in result.output
    # The error message should be the generic one.
    assert "the value you entered was invalid" in result.output", "path": "tests/test_prompt_hide_input.py"}
